INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','imperatives','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"imperatives","title":"Commands, requests and suggestions","level":"A1","order":12,"summary":"Give instructions with a base verb, make them negative, and suggest actions together.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["The unspoken subject","Negative instructions","Suggestions with let’s","Polite requests"],"rules":[{"title":"The unspoken subject","explanation":"An imperative often begins with the **base verb**. Its subject you is usually understood. This lets instructions be short without being incomplete sentences. Tone and context determine whether an imperative is helpful, firm or rude.","pattern":"**Open** the window. / **Please wait** here.","commonMistakes":["Do not add -s to an imperative, even when one person receives the instruction."],"examples":["Give a direct instruction: “**Prepare** the visitor guide, please.”","Give a direct instruction: “**Restore** the old portrait, please.”"],"skill":"form"},{"title":"Negative instructions","explanation":"Use **do not / don’t + base verb** for a prohibition or negative instruction. This also applies to be in a command: Don’t be late. Ordinary statements with be have a different negative pattern.","pattern":"**Don’t touch** the switch. / **Do not be** late.","commonMistakes":["Not touch the switch is not the usual full imperative form."],"examples":["Give a negative instruction: “Do not **prepare** the visitor guide yet.”","Give a negative instruction: “Do not **restore** the old portrait yet.”"],"skill":"meaning"},{"title":"Suggestions with let’s","explanation":"Use **let’s + base verb** to propose an action involving the speaker and other people. Let’s is a contraction of let us in this use. The negative is usually let’s not + base verb.","pattern":"**Let’s take** a break. / **Let’s not hurry**.","commonMistakes":["Lets without an apostrophe is a different verb form: she lets us leave."],"examples":["Suggest doing the task together: “Let’s **prepare** the visitor guide now.”","Suggest doing the task together: “Let’s **restore** the old portrait now.”"],"skill":"contrast"},{"title":"Polite requests","explanation":"Please can soften an instruction. Modal questions with could or would often make a request less direct. After could you or would you, retain the base verb. Please does not make every command appropriate; relationship and situation matter.","pattern":"**Could you close** the door, please?","commonMistakes":["Would you mind takes an -ing form: Would you mind closing the door? It is a different pattern."],"examples":["Complete the polite request: “Could you **prepare** the visitor guide, please?”","Complete the polite request: “Could you **restore** the old portrait, please?”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"c8b861f1-c9ef-547d-a000-0c13124fdcd1","topicSlug":"imperatives","level":"A1","prompt":"Give a direct instruction: “____ the visitor guide, please.”","choices":[{"id":"A","text":"Prepares"},{"id":"B","text":"Prepared"},{"id":"C","text":"To prepare"},{"id":"D","text":"Prepare"}],"answerId":"D","hint":"Use a **base verb** for the instruction.","explanation":"An imperative starts with the base verb **prepare**; the subject you is understood.","keywords":["positive-command"],"skill":"positive-command","contextKey":"imperatives-1","fingerprint":"628f2a2ac8348ed49737c7bf5faa95dec465ac37adff9123b9b74bfc9bae20c5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use a **base verb** for the instruction.","An imperative starts with the base verb **prepare**; the subject you is understood.","Choose **Prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An imperative does not take third-person -s.","B":"A past form does not make a present instruction.","C":"A to-infinitive is not the ordinary direct imperative.","D":"An imperative starts with the base verb **prepare**; the subject you is understood."}}},{"id":"4f6e3715-31b5-516b-a1c5-8d8ee1b0c2ee","topicSlug":"imperatives","level":"A1","prompt":"Give a negative instruction: “Do not ____ the visitor guide yet.”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"prepare"},{"id":"C","text":"prepares"},{"id":"D","text":"preparing"}],"answerId":"B","hint":"Build **do not + base verb**.","explanation":"After **do not**, keep the base form **prepare**.","keywords":["negative-command"],"skill":"negative-command","contextKey":"imperatives-1","fingerprint":"d61006fa78344a114c7e0a90b65ea8e365cec9855b8fd83cb1b78323352488df","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Build **do not + base verb**.","After **do not**, keep the base form **prepare**.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Do not takes a bare infinitive, without to.","B":"After **do not**, keep the base form **prepare**.","C":"Do not already supplies the auxiliary; remove third-person -s.","D":"The imperative after do not needs the base verb, not -ing."}}},{"id":"4ef6172b-c0c1-5b2b-ad65-30c17d594c66","topicSlug":"imperatives","level":"A1","prompt":"Suggest doing the task together: “Let’s ____ the visitor guide now.”","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"prepares"},{"id":"C","text":"to prepare"},{"id":"D","text":"prepare"}],"answerId":"D","hint":"After **let’s**, choose the bare infinitive.","explanation":"**Let’s** takes base **prepare** and includes the speaker in the suggestion.","keywords":["shared-suggestion"],"skill":"shared-suggestion","contextKey":"imperatives-1","fingerprint":"1752e99f1aa05d7bc9cd1095076b2976683b6ce02aeed892d93d4f0e10434f3d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **let’s**, choose the bare infinitive.","**Let’s** takes base **prepare** and includes the speaker in the suggestion.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The -ing form does not follow let’s directly.","B":"Third-person agreement is not used after let’s.","C":"Let’s takes an infinitive without to.","D":"**Let’s** takes base **prepare** and includes the speaker in the suggestion."}}},{"id":"dcbd1d81-d544-5252-a2ab-c4910b1a3b29","topicSlug":"imperatives","level":"A1","prompt":"Complete the polite request: “Could you ____ the visitor guide, please?”","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"to prepare"},{"id":"C","text":"prepare"},{"id":"D","text":"prepares"}],"answerId":"C","hint":"Could makes the request less direct, but the following verb still uses its **base form**.","explanation":"After modal **could**, use base **prepare**. The question functions as a request.","keywords":["polite-modal-request"],"skill":"polite-modal-request","contextKey":"imperatives-1","fingerprint":"ae845ad2209e5b0f356170d897aa7fde8422a8c08bb39e9a4de45332b639f6b2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Could makes the request less direct, but the following verb still uses its **base form**.","After modal **could**, use base **prepare**. The question functions as a request.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Could requires the base verb here, not an -ing form.","B":"There is no to after could in this request.","C":"After modal **could**, use base **prepare**. The question functions as a request.","D":"A modal is not followed by a third-person -s form."}}},{"id":"14c78555-c9c1-5d95-a114-cfa334580a2a","topicSlug":"imperatives","level":"A1","prompt":"Give a direct instruction: “____ the old portrait, please.”","choices":[{"id":"A","text":"Restore"},{"id":"B","text":"Restores"},{"id":"C","text":"Restored"},{"id":"D","text":"To restore"}],"answerId":"A","hint":"Use a **base verb** for the instruction.","explanation":"An imperative starts with the base verb **restore**; the subject you is understood.","keywords":["positive-command"],"skill":"positive-command","contextKey":"imperatives-2","fingerprint":"172ccde19665cf22591a2003b2a8b08ca8e457a01c0cb63172c56c5acb17494f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use a **base verb** for the instruction.","An imperative starts with the base verb **restore**; the subject you is understood.","Choose **Restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An imperative starts with the base verb **restore**; the subject you is understood.","B":"An imperative does not take third-person -s.","C":"A past form does not make a present instruction.","D":"A to-infinitive is not the ordinary direct imperative."}}},{"id":"1cff4f90-af69-501a-a49d-f6cb49e07570","topicSlug":"imperatives","level":"A1","prompt":"Give a negative instruction: “Do not ____ the old portrait yet.”","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"restore"},{"id":"C","text":"restores"},{"id":"D","text":"restoring"}],"answerId":"B","hint":"Build **do not + base verb**.","explanation":"After **do not**, keep the base form **restore**.","keywords":["negative-command"],"skill":"negative-command","contextKey":"imperatives-2","fingerprint":"6cb230aa86b18dc0e2a6186e9453bcb1c2dd3aff9bb5ee9ef689ae5e2c1369ae","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Build **do not + base verb**.","After **do not**, keep the base form **restore**.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Do not takes a bare infinitive, without to.","B":"After **do not**, keep the base form **restore**.","C":"Do not already supplies the auxiliary; remove third-person -s.","D":"The imperative after do not needs the base verb, not -ing."}}},{"id":"f464c7be-1910-5a7b-a734-1d59d3b82870","topicSlug":"imperatives","level":"A1","prompt":"Suggest doing the task together: “Let’s ____ the old portrait now.”","choices":[{"id":"A","text":"restores"},{"id":"B","text":"to restore"},{"id":"C","text":"restore"},{"id":"D","text":"restoring"}],"answerId":"C","hint":"After **let’s**, choose the bare infinitive.","explanation":"**Let’s** takes base **restore** and includes the speaker in the suggestion.","keywords":["shared-suggestion"],"skill":"shared-suggestion","contextKey":"imperatives-2","fingerprint":"638b39986032de529f399903c049e40fd7b684b68247da522a8675fb5490e2dc","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **let’s**, choose the bare infinitive.","**Let’s** takes base **restore** and includes the speaker in the suggestion.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Third-person agreement is not used after let’s.","B":"Let’s takes an infinitive without to.","C":"**Let’s** takes base **restore** and includes the speaker in the suggestion.","D":"The -ing form does not follow let’s directly."}}},{"id":"8183d844-b569-5239-a137-8df7303016a6","topicSlug":"imperatives","level":"A1","prompt":"Complete the polite request: “Could you ____ the old portrait, please?”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"to restore"},{"id":"C","text":"restore"},{"id":"D","text":"restores"}],"answerId":"C","hint":"Could makes the request less direct, but the following verb still uses its **base form**.","explanation":"After modal **could**, use base **restore**. The question functions as a request.","keywords":["polite-modal-request"],"skill":"polite-modal-request","contextKey":"imperatives-2","fingerprint":"9344e13a97b2e69962a5169f5a473f2a42331c000ecebb37b05bea42d852f730","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Could makes the request less direct, but the following verb still uses its **base form**.","After modal **could**, use base **restore**. The question functions as a request.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Could requires the base verb here, not an -ing form.","B":"There is no to after could in this request.","C":"After modal **could**, use base **restore**. The question functions as a request.","D":"A modal is not followed by a third-person -s form."}}},{"id":"5a3d